-- Platform notice documents.
-- A platform notice may carry ONE document: a file a domain owner produced
-- (for example a document the owner issued), staged here byte for byte by the
-- agent pack after verifying its SHA-256 against the owner's manifest. It is
-- never regenerated by R4. The single delivery owner sends it with the
-- notice text as its caption, under the same gates as every outbound.
-- The bytes are kept only while the outbound may still be submitted
-- (pending or dispatching); once the outbound settles they are purged and
-- only the manifest (type, file name, SHA-256, size) remains as evidence.
create table outbound_documents (
  outbound_id   uuid        primary key references outbound_messages (outbound_id),
  content_type  text        not null check (content_type = 'application/pdf'),
  filename      text        not null check (filename ~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,119}$'),
  sha256        text        not null check (sha256 ~ '^[0-9a-f]{64}$'),
  byte_length   integer     not null check (byte_length between 1 and 5242880),
  bytes         bytea,
  created_at    timestamptz not null default clock_timestamp(),
  purged_at     timestamptz,
  constraint outbound_documents_staged_or_purged check ((bytes is null) = (purged_at is not null)),
  constraint outbound_documents_length check (bytes is null or octet_length(bytes) = byte_length)
);
